//! Ids bay puts in ref names (`DESIGN` § 10a): generated by bay from a fixed
//! alphabet, never chosen by a caller.

use std::io::Read;

/// RFC 4648 base32, lower case.
const ALPHABET: &[u8; 32] = b"abcdefghijklmnopqrstuvwxyz234567";

/// Characters in a change id: 40 bits, so ids stay short and a collision is rare.
/// The create-only change ref is still the guard against one.
pub const CHANGE_ID_LEN: usize = 8;

/// A new change id from the operating system's random source.
///
/// # Errors
///
/// The random source cannot be read.
pub fn new_change_id() -> std::io::Result<String> {
    let mut bytes = [0u8; CHANGE_ID_LEN];
    std::fs::File::open("/dev/urandom")?.read_exact(&mut bytes)?;
    Ok(bytes
        .iter()
        .map(|byte| char::from(ALPHABET[usize::from(byte & 31)]))
        .collect())
}

/// Whether `id` is a change id bay could have generated.
#[must_use]
pub fn is_change_id(id: &str) -> bool {
    id.len() == CHANGE_ID_LEN && id.bytes().all(|byte| ALPHABET.contains(&byte))
}

#[cfg(test)]
mod tests {
    use super::{is_change_id, new_change_id};

    #[test]
    fn generated_ids_use_the_alphabet() {
        for _ in 0..100 {
            let id = new_change_id().unwrap();
            assert!(is_change_id(&id), "{id}");
        }
        assert!(!is_change_id("C7K2M4AB"));
        assert!(!is_change_id("c7k2/m4a"));
        assert!(!is_change_id("c7k2m4"));
    }
}
